import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/redact/layer_entropy.dart';
import 'package:test/test.dart';

/// TEMPORARY review probe (gh-1952 review) — NOT part of the PR.
/// Verifies the entropy carve-out's behavior on secret-shaped tokens.
void main() {
  // Same default config the pipeline tests use.
  RedactionConfig cfg() => const RedactionConfig();

  test('probe: padded base64 secret in tool output is NOT entropy-masked',
      () {
    // base64 of 32 random-ish bytes WITH standard padding.
    const padded = 'tZ3mK8vB2nR7xW4cJ9fT5gL0dP1sH6yUqZ3mK8vB2nR=';
    final matches = layerEntropy('echo $padded', cfg());
    // ignore: avoid_print
    print('padded-base64 matches: ${matches.length}');
    expect(matches, isEmpty); // demonstrates the carve-out exempts it
  });

  test('probe: env-style KEY=<random secret> in output is NOT entropy-masked',
      () {
    const line = 'SESSION_KEY=tZ3mK8vB2nR7xW4cJ9fT5gL0dP1sH6y';
    final matches = layerEntropy(line, cfg());
    // ignore: avoid_print
    print('env-style matches: ${matches.length}');
    expect(matches, isEmpty);
  });

  test('probe: pipeline leaves them verbatim (display path)', () {
    final pipeline = RedactionPipeline(registeredSecrets: const []);
    const out =
        'MY_AES_KEY=tZ3mK8vB2nR7xW4cJ9fT5gL0dP1sH6yUqZ3mK8vB2nR= done';
    final redacted = pipeline.redact(out);
    // ignore: avoid_print
    print('redacted: $redacted');
    expect(redacted, out); // raw secret survives into the transcript
  });
}

