import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/agent/agent.dart';
import 'package:flutter_agent_harness/src/agent/events.dart';
import 'package:flutter_agent_harness/src/env/memory_execution_env.dart';
import 'package:flutter_agent_harness/src/redact/redaction_hooks.dart';
import 'package:flutter_agent_harness/src/redact/redaction_pipeline.dart';
import 'package:flutter_agent_harness/src/session/session_repo.dart';
import 'package:flutter_agent_harness/src/tools/builtin_tools.dart';
import 'package:flutter_agent_harness/src/types.dart';
import 'package:test/test.dart';

/// TEMPORARY review probe (gh-1952 review) — NOT part of the PR.
/// Replicates the PR's gh-1952 e2e shape and inspects what the persisted
/// JSONL carries for a REGISTERED secret inside a bash tool-call argument.
final class _FakeStream {
  _FakeStream(this.turns);
  final List<List<Message>> turns;
  int call = 0;
  List<Message> call2(List<Message> messages) {
    final turn = turns[call++];
    return Stream.fromIterable(turn);
  }
}

List<Message> _toolTurn(List<ToolCall> calls) => [
  AssistantMessage(
    content: [TextContent('running')],
    toolCalls: calls,
  ),
  ...calls.map(
    (c) => ToolResultMessage(
      toolCallId: c.id,
      toolName: c.name,
      content: [TextContent('ok')],
    ),
  ),
];

void main() {
  test('probe: does the session JSONL carry a registered secret from bash '
      'call args?', () async {
    const secret = 'reg\$ecretVALUE12345';
    final fake = _FakeStream([
      _toolTurn([
        ToolCall(
          id: 'call-1',
          name: 'bash',
          arguments: {'command': 'flutter run --dart-define=API_KEY=$secret'},
        ),
      ]),
    ]);
    // Stream.fromIterable adapter:
    Stream<Message> streamFn(List<Message> _) async* {
      for (final m in fake.turns[fake.call++]) {
        yield m;
      }
    }

    final shell = RecordingProbeShell();
    final env = MemoryExecutionEnv(cwd: '/work', shell: shell);
    final registry = ToolRegistry()
      ..register(shellTool(env, retryBackoff: Duration.zero));
    final agent = Agent(streamFunction: streamFn, toolRegistry: registry);
    final pipeline = RedactionPipeline(registeredSecrets: [secret]);
    attachRedactionPipeline(agent, pipeline);

    await agent.promptMessage(UserMessage.text('run it'));
    await agent.waitForIdle();

    final fsEnv = MemoryExecutionEnv(cwd: '/work');
    final repo = JsonlSessionRepo(fs: fsEnv, sessionsRoot: '/sessions');
    final session = await repo.create(
      JsonlSessionCreateOptions(cwd: '/work'),
    );
    for (final message in agent.state.messages) {
      await session.appendMessage(message);
    }
    final file = fsEnv.file(
      '/sessions/${session.id}/${session.id}.jsonl',
    );
    final jsonl = file.existsSync() ? file.readAsStringSync() : '';
    // ignore: avoid_print
    print('jsonl length: ${jsonl.length}');
    // ignore: avoid_print
    print('jsonl contains RAW secret (call args): ${jsonl.contains(secret)}');
    // ignore: avoid_print
    print(
      'jsonl contains masked marker: '
      '${jsonl.contains(redactionMarker('Registered Secret'))}',
    );
    // The PR's own e2e never asserts the raw secret's absence; this probe
    // shows whether the call argument persists it verbatim.
    expect(jsonl.contains(secret), isTrue);
  });
}

final class RecordingProbeShell implements Shell {
  String? lastCommand;

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async {
    lastCommand = command;
    return Result.ok(
      const ShellExecResult(stdout: 'trace', stderr: '', exitCode: 0),
    );
  }
}

