import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/redact/layer_entropy.dart';
import 'package:test/test.dart';

/// TEMPORARY re-review probe (gh-1952 round 2) — NOT part of the PR.
/// Independent regression check of the tightened carve-out gate.
void main() {
  RedactionConfig cfg() => const RedactionConfig();

  test('probe: padded-base64 secret is masked again', () {
    const padded = 'tZ3mK8vB2nR7xW4cJ9fT5gL0dP1sH6yUqZ3mK8vB2nR=';
    final matches = layerEntropy('echo $padded', cfg());
    expect(matches, hasLength(1), reason: 'padded base64 must stay masked');
  });

  test('probe: KEY=<random> assignment is masked again', () {
    const line = 'SESSION_KEY=tZ3mK8vB2nR7xW4cJ9fT5gL0dP1sH6y';
    final matches = layerEntropy(line, cfg());
    expect(matches, hasLength(1), reason: 'KEY=<random> must stay masked');
  });

  test('probe: incident define shapes stay clean', () {
    const shapes = <String>[
      'DEF=webgl_geometry_colors_lightsphysicallycorrect',
      'flutter run --dart-define=flutter.inspector.structuredErrors=true',
    ];
    for (final s in shapes) {
      expect(layerEntropy(s, cfg()), isEmpty, reason: s);
    }
  });

  test('probe: pipeline leaves the define verbatim, masks the secret line',
      () {
    final pipeline = RedactionPipeline(registeredSecrets: const []);
    const define =
        'flutter run --dart-define=flutter.inspector.structuredErrors=true';
    expect(pipeline.redact(define), define);
    const line = 'SESSION_KEY=tZ3mK8vB2nR7xW4cJ9fT5gL0dP1sH6y';
    expect(pipeline.redact(line), isNot(contains(line.substring(12))));
  });
}

